import 'package:flutter/material.dart';

import 'dashboard_controller.dart';
import 'models.dart';

const _green = Color(0xFF174A38);
const _ink = Color(0xFF1F2B24);
const _muted = Color(0xFF6B7A70);
const _line = Color(0xFFE0E8E0);
const _red = Color(0xFF9E332B);

class DesignDashboard extends StatefulWidget {
  const DesignDashboard({super.key, required this.controller, required this.baseUrl,
    required this.onEditAddress, required this.onExportLog, required this.onExportCsv});
  final DashboardController controller;
  final String baseUrl;
  final VoidCallback onEditAddress;
  final Future<void> Function(BuildContext) onExportLog;
  final Future<void> Function(BuildContext) onExportCsv;
  @override State<DesignDashboard> createState() => _DesignDashboardState();
}

class _DesignDashboardState extends State<DesignDashboard> {
  int tab = 0;
  DashboardController get c => widget.controller;
  @override Widget build(BuildContext context) => AnimatedBuilder(animation: c, builder: (context, _) {
    final connected = c.status != null && c.errorMessage == null;
    return Scaffold(
      appBar: AppBar(toolbarHeight: 54, backgroundColor: Colors.white, foregroundColor: _ink, elevation: 0, titleSpacing: 20,
        title: const Row(children: [
          _BrandMark(), SizedBox(width: 7), Text('Peo Yame', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w700, color: _green)),
        ]),
        actions: [Padding(padding: const EdgeInsets.only(right: 18), child: _Pill(text: connected ? '● Online' : '● Offline', color: connected ? const Color(0xFFE8F5EB) : const Color(0xFFFFEBE8), textColor: connected ? _green : _red))],
      ),
      body: Column(children: [
        if (c.errorMessage != null) Padding(padding: const EdgeInsets.fromLTRB(18, 8, 18, 0), child: _Notice(c.errorMessage!, warning: true)),
        Expanded(child: Center(child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 520),
          child: RefreshIndicator(onRefresh: c.refresh, child: IndexedStack(index: tab, children: [
            _overview(), _trends(), _alerts(), _settings(),
          ])),
        ))),
      ]),
      bottomNavigationBar: _Navigation(selected: tab, onSelect: (v) => setState(() => tab = v)),
    );
  });

  Widget _overview() => ListView(physics: const AlwaysScrollableScrollPhysics(), padding: const EdgeInsets.fromLTRB(18, 14, 18, 24), children: [
    const Text('Good morning, Olerato', textAlign: TextAlign.center, style: TextStyle(fontSize: 22, height: 1.25, fontWeight: FontWeight.w700, color: _ink)),
    const SizedBox(height: 3), const Text('Here’s how your harvest is doing today', textAlign: TextAlign.center, style: TextStyle(fontSize: 12, color: _muted)),
    const SizedBox(height: 12), const _Notice('Demo data · sensor and SMS are not connected', warning: true), const SizedBox(height: 10),
    if (c.status case final s?) ...[
      _StatusCard(s), const SizedBox(height: 8),
      Row(children: [Expanded(child: _Metric(label: 'Temperature', value: s.latest == null ? '—' : '${s.latest!.temperature.toStringAsFixed(1)}°C', limit: 'Allowed ${_fmt(s.threshold.minTemp)}–${_fmt(s.threshold.maxTemp)}°C')), const SizedBox(width: 10), Expanded(child: _Metric(label: 'Humidity', value: s.latest == null ? '—' : '${s.latest!.humidity.toStringAsFixed(0)}%', limit: 'Allowed ${_fmt(s.threshold.minHumidity)}–${_fmt(s.threshold.maxHumidity)}%'))]),
      const SizedBox(height: 12), _Section('Harvest', trailing: TextButton(onPressed: _chooseHarvest, child: const Text('Change'))), _Harvest(s, onChanged: c.setHarvest),
    ] else if (c.isLoading) const Padding(padding: EdgeInsets.all(28), child: Center(child: CircularProgressIndicator())) else const _Card(child: Text('Waiting for the monitor to connect.', style: TextStyle(color: _muted))),
    const SizedBox(height: 13), _Section('Conditions over time', trailing: TextButton(onPressed: () => setState(() => tab = 1), child: const Text('24 hours'))),
    _MiniChart(points: c.trends), const SizedBox(height: 13), _Section('Recent alerts', trailing: TextButton(onPressed: () => setState(() => tab = 2), child: const Text('See all'))),
    if (c.alerts.isEmpty) const _Card(child: Text('No alerts yet. Your storage conditions look quiet.', style: TextStyle(color: _muted))) else ...c.alerts.take(2).map((a) => _AlertCard(a, threshold: c.status?.threshold, onAcknowledge: () => c.acknowledgeAlert(a.id))),
  ]);

  Widget _trends() => ListView(physics: const AlwaysScrollableScrollPhysics(), padding: const EdgeInsets.fromLTRB(18, 12, 18, 24), children: [
    _PageTitle('Trends', trailing: IconButton(onPressed: c.refresh, icon: const Icon(Icons.refresh_rounded, color: _green))),
    _Ranges(selected: c.trendRange, onSelect: c.setTrendRange), const SizedBox(height: 12),
    _TrendChart(points: c.trends, error: c.trendError, latest: c.status?.latest), const SizedBox(height: 14),
    const _Section('At a glance'),
    Row(children: [Expanded(child: _Summary('LOWEST', _extreme(true))), const SizedBox(width: 10), Expanded(child: _Summary('HIGHEST', _extreme(false)))]),
    const SizedBox(height: 14), _Section('Recent readings', trailing: TextButton(onPressed: c.refresh, child: const Text('View all'))),
    _ReadingList(readings: c.history.reversed.take(8).toList()),
  ]);

  String _extreme(bool low) {
    final values = c.trends.map((p) => p.temperature).toList();
    if (values.isEmpty) return '—';
    final n = low ? values.reduce((a,b) => a < b ? a : b) : values.reduce((a,b) => a > b ? a : b);
    return '${n.toStringAsFixed(1)}°C';
  }

  Widget _alerts() {
    final open = c.alerts.where((a) => !a.acknowledged).toList();
    final done = c.alerts.where((a) => a.acknowledged).toList();
    return ListView(physics: const AlwaysScrollableScrollPhysics(), padding: const EdgeInsets.fromLTRB(18, 12, 18, 24), children: [
      _PageTitle('Alerts', trailing: IconButton(onPressed: c.refresh, icon: const Icon(Icons.more_vert, color: _green))),
      _AlertSummary(open.length), const SizedBox(height: 16), _Section('Needs attention', trailing: const Text('Newest first', style: TextStyle(fontSize: 11, color: _green))), const SizedBox(height: 6),
      if (open.isEmpty) const _Card(child: Text('You’re all caught up. No alerts need attention.', style: TextStyle(color: _muted))) else ...open.map((a) => _AlertCard(a, threshold: c.status?.threshold, prominent: true, onAcknowledge: () => c.acknowledgeAlert(a.id))),
      const SizedBox(height: 14), _Section('Earlier', trailing: Text('${done.length} records', style: const TextStyle(fontSize: 11, color: _green))), const SizedBox(height: 6),
      if (done.isEmpty) const _ResolvedEmpty() else ...done.map((a) => _Resolved(a)),
      const SizedBox(height: 12), const _SmsNote(),
    ]);
  }

  Widget _settings() => ListView(physics: const AlwaysScrollableScrollPhysics(), padding: const EdgeInsets.fromLTRB(18, 12, 18, 24), children: [
    const _PageTitle('Settings'), const _Section('Connection'),
    _Connection(address: widget.baseUrl, connected: c.status != null && c.errorMessage == null, onEdit: widget.onEditAddress), const SizedBox(height: 14),
    const _Section('Harvest limits'), if (c.status case final s?) _Limits(s, onChanged: c.setHarvest) else const _Card(child: Text('Harvest limits appear when connected.', style: TextStyle(color: _muted))),
    const SizedBox(height: 14), const _Section('Data & alerts'),
    Builder(builder: (ctx) => _Action('Export activity log', Icons.file_upload_outlined, () => widget.onExportLog(ctx))), const SizedBox(height: 7),
    Builder(builder: (ctx) => _Action('Export readings for Excel', Icons.file_download_outlined, () => widget.onExportCsv(ctx))),
    const SizedBox(height: 8), const _SmsNote(compact: true), const SizedBox(height: 5),
    OutlinedButton.icon(onPressed: c.isTriggering ? null : c.triggerDemoBreach, icon: const Icon(Icons.warning_amber_rounded), label: const Text('Trigger demo alert')),
  ]);

  Future<void> _chooseHarvest() async {
    final current = c.status?.threshold.commodity;
    final picked = await showModalBottomSheet<String>(context: context, builder: (ctx) => SafeArea(child: Column(mainAxisSize: MainAxisSize.min, children: [
      const Padding(padding: EdgeInsets.all(16), child: Text('Select harvest', style: TextStyle(fontSize: 18, fontWeight: FontWeight.w700))),
      for (final crop in ['Maize', 'Tomato']) ListTile(title: Text(crop), trailing: current == crop ? const Icon(Icons.check, color: _green) : null, onTap: () => Navigator.pop(ctx, crop)),
    ])));
    if (picked != null && picked != current) await c.setHarvest(picked);
  }
}

class _BrandMark extends StatelessWidget { const _BrandMark(); @override Widget build(BuildContext context) => Container(width: 22, height: 22, decoration: const BoxDecoration(color: Color(0xFFB8DE9E), shape: BoxShape.circle), child: const Icon(Icons.eco_rounded, size: 14, color: _green)); }
