class _Bars extends CustomPainter { const _Bars({required this.points,required this.color}); final List<TrendPoint> points; final Color color; @override void paint(Canvas canvas,Size size){ final vals=points.map((p)=>p.temperature).toList(); if(vals.isEmpty)return; final grid=Paint()..color=const Color(0xFFE6ECE5)..strokeWidth=.7; for(var i=1;i<=3;i++){final y=size.height*i/4;canvas.drawLine(Offset.zero.translate(0,y),Offset(size.width,y),grid);} final n=vals.length>30?30:vals.length; final dx=size.width/n; final lo=vals.reduce((a,b)=>a<b?a:b), hi=vals.reduce((a,b)=>a>b?a:b), span=hi-lo; final paint=Paint()..color=color; for(var i=0;i<n;i++){final v=vals[(i*(vals.length-1)/(n-1==0?1:n-1)).round()]; final h=span==0?size.height*.55:(size.height*(.25+.65*(v-lo)/span)); final rect=RRect.fromRectAndRadius(Rect.fromLTWH(i*dx+dx*.25,size.height-h,dx*.52,h),const Radius.circular(3));canvas.drawRRect(rect,paint);} } @override bool shouldRepaint(covariant _Bars old)=>old.points!=points||old.color!=color; }
