String _fmt(double n)=>n==n.roundToDouble()?n.toStringAsFixed(0):n.toStringAsFixed(1);
String _time(String value){final d=DateTime.tryParse(value)?.toLocal(); if(d==null)return value; final h=d.hour%12==0?12:d.hour%12; return '${d.hour==0||d.hour<12?'Today':'Today'} · $h:${d.minute.toString().padLeft(2,'0')} ${d.hour<12?'AM':'PM}';}
String _alertTitle(Alert a, [Threshold? threshold]) { final message = a.message; final temp = double.tryParse(RegExp('([0-9.]+)\\u00B0C').firstMatch(message)?.group(1) ?? ''); final humidity = double.tryParse(RegExp(r', ([0-9.]+)% RH').firstMatch(message)?.group(1) ?? ''); final tempOut = threshold != null && temp != null && (temp < threshold.minTemp || temp > threshold.maxTemp); final humidityOut = threshold != null && humidity != null && (humidity < threshold.minHumidity || humidity > threshold.maxHumidity); if (humidityOut && !tempOut) return 'Humidity above safe range'; if (tempOut && !humidityOut) return 'Temperature above safe range'; return 'Storage conditions outside safe range'; }
